"""Generate all nine source CFL events and their active magnitudes."""

from fractions import Fraction

GRID = 8
MAGNITUDES = (0, 1, 2, 3)
EVENTS = 9
X_LIMITS = (2, 5)
Y_LIMITS = (1, 5)
SHOTS = 2048


def schedule() -> tuple[tuple[Fraction, tuple[int, ...]], ...]:
    """Advance to the next crossing of a grid spacing by a source magnitude."""
    crossings = {speed: Fraction(1, speed) for speed in MAGNITUDES if speed}
    events = []
    for _ in range(EVENTS):
        instant = min(crossings.values())
        moving = tuple(
            speed for speed, crossing in crossings.items() if crossing == instant
        )
        for speed in moving:
            crossings[speed] += Fraction(1, speed)
        events.append((instant, moving))
    return tuple(events)


def active_magnitudes() -> tuple[int, ...]:
    """Flatten simultaneous moves in increasing magnitude as in the source."""
    return tuple(speed for _, active in schedule() for speed in active)

"""Coherent streaming and reflection express the lattice boundary rules."""

from flagquantum.synth import QBit, QNum, X, control, qfunc


@qfunc
def forward(position: QNum) -> None:
    position += 1


@qfunc
def backward(position: QNum) -> None:
    position -= 1


@qfunc
def stream(active: int, position: QNum, velocity: QNum, direction: QBit) -> None:
    control(
        (direction >= 1) & (velocity == active),
        lambda: forward(position),
    )
    control(
        (direction <= 0) & (velocity == active),
        lambda: backward(position),
    )


@qfunc
def reflect(
    active: int,
    edge_a: int,
    edge_b: int,
    low: int,
    high: int,
    change_position: QNum,
    fixed_position: QNum,
    velocity: QNum,
    direction: QBit,
) -> None:
    control(
        (fixed_position >= low)
        & (fixed_position <= high)
        & (velocity == active)
        & ((change_position == edge_a) | (change_position == edge_b)),
        lambda: X(direction),
    )


@qfunc
def lattice_step(
    active: int, x: QNum, y: QNum, vx: QBit, vy: QBit, ux: QNum, uy: QNum
) -> None:
    stream(active, x, ux, vx)
    stream(active, y, uy, vy)
    reflect(active, 1, 5, 2, 5, y, x, uy, vy)
    reflect(active, 2, 5, 1, 5, x, y, ux, vx)
